#include "file_io.hpp"
#include <iostream>
int main(){namespace fs=std::filesystem;using namespace ofo;auto dir=fs::temp_directory_path()/fs::u8path(u8"openfo-файли-ї");try{fs::create_directories(dir);auto path=dir/fs::u8path(u8"дані.bin");std::string content("a\0b",3);write_file_atomic(path,content);auto b=read_file(path);if(std::string(b.begin(),b.end())!=content)throw std::runtime_error("byte mismatch");write_file_atomic(path,"replacement");b=read_file(path);if(std::string(b.begin(),b.end())!="replacement")throw std::runtime_error("replace mismatch");bool rejected=false;try{read_file(path,2);}catch(...){rejected=true;}if(!rejected)throw std::runtime_error("limit ignored");write_file_atomic(path,"");if(!read_file(path).empty())throw std::runtime_error("empty file");rejected=false;try{read_file(dir/"absent");}catch(...){rejected=true;}if(!rejected)throw std::runtime_error("missing file accepted");fs::remove_all(dir);std::cout<<"Unicode IO, binary bytes, atomic replacement, empty/missing files and limits passed\n";return 0;}catch(const std::exception&e){fs::remove_all(dir);std::cerr<<e.what();return 1;}}
